35	#ifndef D_SEQUENTIAL_PICKER_H
36	#define D_SEQUENTIAL_PICKER_H
37	
38	#include "common.h"
39	
40	#include <deque>
41	#include <memory>
42	#include <functional>
43	
44	namespace aria2 {
45	
46	template <typename T> class SequentialPicker {
47	private:
48	  std::deque<std::unique_ptr<T>> entries_;
49	  std::unique_ptr<T> pickedEntry_;
50	
51	public:
52	  bool isPicked() const { return pickedEntry_.get(); }
53	
54	  const std::unique_ptr<T>& getPickedEntry() const { return pickedEntry_; }
55	
56	  void dropPickedEntry() { pickedEntry_.reset(); }
57	
58	  bool hasNext() const { return !entries_.empty(); }
59	
60	  T* pickNext()
61	  {
62	    if (hasNext()) {
63	      pickedEntry_ = std::move(entries_.front());
64	      entries_.pop_front();
65	      return pickedEntry_.get();
66	    }
67	    return nullptr;
68	  }
69	
70	  void pushEntry(std::unique_ptr<T> entry)
71	  {
72	    entries_.push_back(std::move(entry));
73	  }
74	
75	  size_t countEntryInQueue() const { return entries_.size(); }
76	
77	  bool isPicked(const std::function<bool(const T&)>& pred) const
78	  {
79	    return pickedEntry_ && pred(*pickedEntry_);
80	  }
81	
82	  bool isQueued(const std::function<bool(const T&)>& pred) const
83	  {
84	    for (auto& e : entries_) {
85	      if (pred(*e)) {
86	        return true;
87	      }
88	    }
89	    return false;
90	  }
91	};
