114	template <typename InputIterator, typename OutputIterator>
115	OutputIterator enumerateInFlightHosts(InputIterator first, InputIterator last,
116	                                      OutputIterator out)
117	{
118	  for (; first != last; ++first) {
119	    uri_split_result us;
120	    if (uri_split(&us, (*first)->getUri().c_str()) == 0) {
121	      *out++ = uri::getFieldString(us, USR_HOST, (*first)->getUri().c_str());
122	    }
123	  }
124	  return out;
125	}
