128	std::shared_ptr<Request> FileEntry::getRequestWithInFlightHosts(
129	    URISelector* selector, bool uriReuse,
130	    const std::vector<std::pair<size_t, std::string>>& usedHosts,
131	    const std::string& referer, const std::string& method,
132	    const std::vector<std::string>& inFlightHosts)
133	{
134	  std::shared_ptr<Request> req;
135	
136	  for (int g = 0; g < 2; ++g) {
137	    std::vector<std::string> pending;
138	    std::vector<std::string> ignoreHost;
139	    while (1) {
140	      std::string uri = selector->select(this, usedHosts);
141	      if (uri.empty()) {
142	        break;
143	      }
144	      req = std::make_shared<Request>();
145	      if (req->setUri(uri)) {
146	        if (std::count(std::begin(inFlightHosts), std::end(inFlightHosts),
147	                       req->getHost()) >= maxConnectionPerServer_) {
148	          pending.push_back(uri);
149	          ignoreHost.push_back(req->getHost());
150	          req.reset();
151	          continue;
152	        }
153	        if (referer == "*") {
154	          // Assuming uri has already been percent-encoded.
155	          req->setReferer(uri);
156	        }
157	        else {
158	          req->setReferer(util::percentEncodeMini(referer));
159	        }
160	        req->setMethod(method);
161	        spentUris_.push_back(uri);
162	        inFlightRequests_.insert(req);
163	        break;
164	      }
165	      else {
166	        req.reset();
167	      }
168	    }
169	    uris_.insert(std::begin(uris_), std::begin(pending), std::end(pending));
170	    if (g == 0 && uriReuse && !req && uris_.size() == pending.size()) {
171	      // Reuse URIs other than ones in pending
172	      reuseUri(ignoreHost);
173	      continue;
174	    }
175	
176	    break;
177	  }
178	  return req;
179	}
