182	    URISelector* selector, bool uriReuse,
183	    const std::vector<std::pair<size_t, std::string>>& usedHosts,
184	    const std::string& referer, const std::string& method)
185	{
186	  std::shared_ptr<Request> req;
187	  if (requestPool_.empty()) {
188	    std::vector<std::string> inFlightHosts;
189	    enumerateInFlightHosts(std::begin(inFlightRequests_),
190	                           std::end(inFlightRequests_),
191	                           std::back_inserter(inFlightHosts));
192	    return getRequestWithInFlightHosts(selector, uriReuse, usedHosts, referer,
193	                                       method, inFlightHosts);
194	  }
195	
196	  // Skip Request object if it is still
197	  // sleeping(Request::getWakeTime() < global::wallclock()).  If all
198	  // pooled objects are sleeping, we may return first one.  Caller
199	  // should inspect returned object's getWakeTime().
200	  auto i = std::begin(requestPool_);
201	  for (; i != std::end(requestPool_); ++i) {
202	    if ((*i)->getWakeTime() <= global::wallclock()) {
203	      break;
204	    }
