212	    enumerateInFlightHosts(std::begin(requestPool_), std::end(requestPool_),
213	                           std::back_inserter(inFlightHosts));
214	
215	    req = getRequestWithInFlightHosts(selector, uriReuse, usedHosts, referer,
216	                                      method, inFlightHosts);
217	    if (!req || req->getUri() == (*std::begin(requestPool_))->getUri()) {
218	      i = std::begin(requestPool_);
219	    }

